import concurrent.futures,json,pathlib,time,urllib.request,urllib.error
URL='https://app.ontrackegy.com/ayo/'
checks=['','app.js?v=13','style.css?v=13','ayo-mic-stt.js','audio-worklet.js','api.php?action=status']
def probe(path):
 try:
  with urllib.request.urlopen(urllib.request.Request(URL+path,headers={'User-Agent':'AYO-V13-VERIFY/1','Cache-Control':'no-cache'}),timeout=8) as r:
   data=r.read(120000);status=r.status
  if path=='': good=b'personaMode' in data and b'confirmTranscript' in data and b'15:00' in data
  elif path.startswith('api.php'):
   obj=json.loads(data);good=obj.get('config',{}).get('maxSeconds')==900 and obj.get('config',{}).get('personaMode')=='flirty'
  elif path.startswith('app.js'):good=b'provider_fallback' in data and b'firstAudioMs' in data
  elif path.startswith('ayo-mic'):good=b'LINEAR16' in data and b'voiceMs' in data
  else:good=len(data)>200
  return {'path':path,'http':status,'ok':good and status==200}
 except Exception as e:return {'path':path,'error':type(e).__name__,'ok':False}
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool:checks=list(pool.map(probe,checks))
CREDS=pathlib.Path('/home/appontrack/.ayo-private/credentials.json')
providers={}
if CREDS.is_file() and not CREDS.is_symlink():
 try:
  keys=json.loads(CREDS.read_text())
  for name,key in [('apinex','apinex'),('omnira-b','omnira')]:
   providers[name]={'credential_present':bool(keys.get(key))}
  def test(name):
   keyname='apinex' if name=='apinex' else 'omnira'
   key=keys.get(keyname,'')
   if not isinstance(key,str) or len(key)<10:return {'configured':False}
   target='https://api.apinex.bond/v1/chat/completions' if name=='apinex' else 'https://v2.omnira-ai.net/v1/chat/completions'
   model='free/gemini-3.8-flash' if name=='apinex' else 'deepseek-v4-flash'
   body=json.dumps({'model':model,'messages':[{'role':'user','content':'قل حاضر فقط'}],'max_tokens':25,'stream':True}).encode()
   req=urllib.request.Request(target,data=body,headers={'Authorization':'Bearer '+key,'Content-Type':'application/json','Accept':'text/event-stream','User-Agent':'OnTrack-AYO-Provider-Health/1'},method='POST')
   begin=time.monotonic()
   try:
    with urllib.request.urlopen(req,timeout=11) as r:
     first=r.read(180)
     return {'configured':True,'http':r.status,'first_byte_ms':round((time.monotonic()-begin)*1000),'received_data':bool(first)}
   except urllib.error.HTTPError as ex:return {'configured':True,'http':ex.code,'elapsed_ms':round((time.monotonic()-begin)*1000)}
   except Exception as ex:return {'configured':True,'error':type(ex).__name__,'elapsed_ms':round((time.monotonic()-begin)*1000)}
  with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
   futures={name:pool.submit(test,name) for name in ['apinex','omnira-b']}
   providers={name:task.result() for name,task in futures.items()}
 except Exception as ex:providers={'diagnostic_error':type(ex).__name__}
print(json.dumps({'checks':checks,'checks_pass':all(c['ok'] for c in checks),'provider_probes':providers}),flush=True)
if not all(c['ok'] for c in checks):raise SystemExit(2)
